sys_module.content:
(function routePartnerIncidentToStoreIssue(current, previous) {
    var routableTypes = ['order_not_ready', 'wrong_items_packed', 'unsafe_store_conditions'];
    if (routableTypes.indexOf(current.getValue('incident_type')) === -1) {
        return;
    }

    var issueGr = new GlideRecord('x_2145749_qc_store_issue');
    issueGr.initialize();
    issueGr.setValue('dark_store', current.getValue('dark_store'));
    issueGr.setValue('issue_category', 'other');
    issueGr.setValue('severity', current.getValue('severity'));
    issueGr.setValue('description', current.getValue('description'));
    issueGr.setValue('source_partner_incident', current.getUniqueValue());
    issueGr.insert();

    current.setValue('state', 'routed_to_store');
    current.update();
})(current, previous);
